import{z as o,x as l,o as B,c as s,q as e,j as n,D as a,d as i,s as A,S as r}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"久期免疫","description":"","frontmatter":{"title":"久期免疫","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bm2-duration-immunization.md","filePath":"quant/bm2-duration-immunization.md","lastUpdated":1791063341000}'),d={name:"quant/bm2-duration-immunization.md"};function p(m,E,u,D,_,C){const t=l("Mermaid");return B(),s("div",null,[E[2]||(E[2]=e('<h1 id="久期免疫" tabindex="-1">久期免疫 <a class="header-anchor" href="#久期免疫" aria-label="Permalink to &quot;久期免疫&quot;">​</a></h1><div class="epigraph"><p>免疫不是消灭利率风险，而是让资产与负债在第一次导数上互相抵消——剩下的二阶项与曲线形状，才是组合管理真正要谈判的东西。</p><footer>—— 据 Redington, Review of the Principles of Life-Office Valuations, Journal of the Institute of Actuaries, 1952 整理</footer></div><p><a href="/quant/qo-map">上一课</a>把利率与信用两条线收进三个案例，判据落在资金链与条款上；2022 年 gilt 螺旋那一案，主角正是没管好负债匹配的债券组合。本课程转向持有方视角，重讲「拿着一张负债表怎么管债券」：先写最干净的版本——久期免疫，再谈 LDI、指数化与期货互换，最后收在信用与案例。本课要回答：一笔确定日期的负债，如何选资产让组合在一阶上不感知利率。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/quant/duration-convexity">久期与凸性</a>把久期定义为价格对收益率的敏感度，那是测量；本课把久期当工具用。缺口在这里：一家机构三年后要付一笔定额负债，今天把钱放进国债，收益率一变，资产现值与负债现值同时动、幅度却不同——负债端由<a href="/quant/curve-bootstrap">自助曲线</a>折现，资产端由自己的到期结构决定，缺口恰好落在一阶导数上。「买一只到期日相同的债券」看似解决，可市场未必有那个到期、流动性未必接得住，于是问题变成：用可得的券拼出与负债同现值、同久期的组合，并在时间与利率都漂移时保持住这个匹配。</p><p><span class="marginnote">常见误区：「买到期日相同的债券就免疫了」。实际上付息债的久期总是小于其到期期限——一只 10 年期、票息 3% 的国债久期约 8.8 年，而 10 年零息债的久期才恰好是 10 年。所以按到期日挑券和按久期匹配是两件事，票息越高，两者差得越远。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>免疫条件有两条：资产现值等于负债现值，资产 Macaulay 久期等于负债久期，即 \\(D_A V_A = D_L V_L\\)。负债在 \\(H\\) 年且市场恰有 \\(H\\) 年零息债时，买入持有即完全匹配；否则用付息债拼装，组合久期按市值加权逼近 \\(H\\)。同等久期下仍有结构选择：子弹（集中在中段）与哑铃（短长两端）久期相同、凸性不同，这是留给后文机制的伏笔。匹配不是一次性的：时间流逝让付息债的久期比目标到期掉得慢，利率变动又改变久期本身，所以免疫是一个「匹配—漂移—再平衡」的循环，再平衡频率在交易成本与漂移缺口之间定价。</p>',8)),(B(),n(r,null,{default:a(()=>[A(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E8%B4%9F%E5%80%BA%EF%BC%9A%E5%88%B0%E6%9C%9F%20H%20%E4%B8%8E%E7%8E%B0%E5%80%BC%22%5D%20--%3E%20M%5B%22%E5%8C%B9%E9%85%8D%E8%B5%84%E4%BA%A7%EF%BC%9A%E7%8E%B0%E5%80%BC%E7%9B%B8%E7%AD%89%E3%80%81%E4%B9%85%E6%9C%9F%E7%9B%B8%E7%AD%89%22%5D%0A%20%20B%5B%22%E5%AD%90%E5%BC%B9%E7%BB%84%E5%90%88%22%5D%20--%3E%20M%0A%20%20BB%5B%22%E5%93%91%E9%93%83%E7%BB%84%E5%90%88%22%5D%20--%3E%20M%0A%20%20M%20--%3E%20S%5B%22%E5%88%A9%E7%8E%87%E5%8F%98%E5%8A%A8%22%5D%0A%20%20S%20--%3E%20F%5B%22%E4%B8%80%E9%98%B6%E6%8D%9F%E7%9B%8A%E7%9B%B8%E4%BA%92%E6%8A%B5%E6%B6%88%22%5D%0A%20%20S%20--%3E%20R%5B%22%E6%AE%8B%E5%B7%AE%EF%BC%9A%E5%87%B8%E6%80%A7%E5%B7%AE%E4%B8%8E%E6%9B%B2%E7%BA%BF%E6%89%AD%E8%BD%AC%22%5D%0A%20%20R%20--%3E%20RB%5B%22%E8%B6%85%E9%98%88%E5%80%BC%E5%88%99%E5%86%8D%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20RB%20--%3E%20M%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>免疫为什么成立：价格变动按泰勒展开，一阶项是 \\(-DV\\,\\Delta y\\)，两端口径相同即相互抵消，与 \\(\\Delta y\\) 的正负无关。剩下的残差有两类。其一是二阶项 \\(\\tfrac{1}{2}(C_A V_A - C_L V_L)\\Delta y^2\\)：哑铃比子弹凸性大，平行大幅移动时占便宜——凸性差是免疫组合唯一「免费」的方向性优势。其二是曲线形状：单一久期只对水平因子免疫，陡平化带来的损益是一阶的、不会被抵消。<a href="/quant/curve-pca">Litterman 与 Scheinkman 的主成分分解</a>说明国债收益的方差绝大部分由水平、陡峭、曲率三因子承载，所以严格的免疫应把 <a href="/quant/key-tenor-dv01">关键期限 DV01</a> 按桶对齐，而不是只对一个标量。经典的重投资机制也在此处：利率上行造成的资本损失由再投资收益的上升补偿，补偿之所以恰好兑现，靠的正是上述匹配与再平衡纪律。</p><p><span class="marginnote">持有不动不等于保持免疫：面值购入的 10 年期、3% 年付票息债 Macaulay 久期约 8.8 年；一年后降到约 8.0 年，而免疫目标只剩 9 年——缺口近 1 年。不同时再平衡，免疫就随时间悄悄失效。</span></p>',3)),(B(),n(r,null,{default:a(()=>[A(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E6%A0%B7%E4%B9%85%E6%9C%9F%EF%BC%8C%E5%88%B8%E6%80%8E%E4%B9%88%E6%91%86%22%5D%20--%3E%20B1%5B%22%E5%AD%90%E5%BC%B9%EF%BC%9A%E9%9B%86%E4%B8%AD%E5%9C%A8%E7%9B%AE%E6%A0%87%E5%88%B0%E6%9C%9F%E9%99%84%E8%BF%91%22%5D%0A%20%20Q%20--%3E%20B2%5B%22%E5%93%91%E9%93%83%EF%BC%9A%E7%9F%AD%E7%AB%AF%E4%B8%8E%E9%95%BF%E7%AB%AF%E5%90%84%E6%94%BE%E4%B8%80%E9%83%A8%E5%88%86%22%5D%0A%20%20B1%20--%3E%20S1%5B%22%E5%B9%B3%E8%A1%8C%E5%B0%8F%E5%B9%85%E7%A7%BB%E5%8A%A8%EF%BC%9A%E4%B8%A4%E8%80%85%E6%8D%9F%E7%9B%8A%E5%87%A0%E4%B9%8E%E4%B8%80%E6%A0%B7%22%5D%0A%20%20B2%20--%3E%20S2%5B%22%E5%B9%B3%E8%A1%8C%E5%A4%A7%E5%B9%85%E7%A7%BB%E5%8A%A8%EF%BC%9A%E5%93%91%E9%93%83%E5%87%B8%E6%80%A7%E5%A4%A7%EF%BC%8C%E5%8D%A0%E4%BC%98%22%5D%0A%20%20B1%20--%3E%20T%5B%22%E6%9B%B2%E7%BA%BF%E9%99%A1%E5%B9%B3%E5%8C%96%EF%BC%9A%E4%B8%A4%E8%80%85%E9%83%BD%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20B2%20--%3E%20T%0A%20%20T%20--%3E%20K%5B%22%E8%A7%A3%E6%B3%95%EF%BC%9A%E6%8C%89%E5%85%B3%E9%94%AE%E6%9C%9F%E9%99%90%E6%A1%B6%E5%AF%B9%E9%BD%90%20DV01%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p><span class="marginnote">数字实例：一阶项 \\(-DV\\,\\Delta y\\) 有多准？取组合现值 1000 万、久期 8.8，收益率上行 0.1%（10bp），一阶损失约 \\(1000\\text{万} \\times 8.8 \\times 0.001 = 8.8\\) 万元。资产端和负债端都按同一笔账算，只要两边 \\(DV\\) 相等，这 8.8 万元就同时出现在盈亏两侧、互相抵消。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>免疫的保证只对收益率的小幅平行移动成立。大幅移动时凸性差进入主导，曲线扭转时单久期匹配甚至不保证方向。久期也不覆盖信用：国债久期对利差变动失明，含信用资产的组合要另配利差久期口径。多笔负债时标量匹配不够，要么按桶对齐 DV01 向量，要么直接现金流匹配——后者对曲线形状免疫但要为每个支付日找券，长端往往买不到。最后，免疫目标用的是折现口径的负债，监管口径与经济口径的折现率不同时，「免疫了什么」要先在纸面上说清，否则两条口径的缺口会在报告里互相揭短。</p><p><span class="marginnote">直觉类比：久期匹配像给天平两边放等重砝码——小幅度倾斜时两边同步下沉，指针不动；凸性则是砝码下面的减震弹簧，行情剧烈晃动时弹簧能吸收二次冲击，凸性大的一方受伤更轻。但天平只对「整体上下」敏感，若一边被抬起另一边被压下（曲线扭转），天平照样翻。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>免疫条件：资产与负债现值相等、久期相等，一阶损益对平移相互抵消。</li><li>匹配是循环不是动作：时间与利率都让久期漂移，再平衡频率是成本与缺口的交易。</li><li>残差有两类：凸性差（二阶）与曲线扭转（一阶），后者要求按关键期限桶匹配。</li><li>久期免疫不覆盖利差风险，也不自动处理多负债与口径差异。</li><li>出处：据 Redington（1952）与 Fabozzi 相关章节整理；因子分解口径出自 Litterman and Scheinkman, Journal of Fixed Income, 1991。</li></ul>',6))])}const f=o(d,[["render",p]]);export{h as __pageData,f as default};
